// ── 픽셀 스프라이트 렌더러 (오프스크린 캐싱) ─────────────────────
// 매 프레임 픽셀 단위 fillRect를 반복하지 않도록, 스프라이트를 1픽셀=1px
// 오프스크린 캔버스에 한 번만 굽고 이후에는 drawImage 한 번으로 그린다.
const _spriteCache = new WeakMap();

// 밝게(f>0)/어둡게(f<0)
function _shadeColor(hex, f) {
    const n = parseInt(hex.slice(1), 16);
    let r = (n >> 16) & 255, g = (n >> 8) & 255, b = n & 255;
    if (f >= 0) { r += (255 - r) * f; g += (255 - g) * f; b += (255 - b) * f; }
    else { r *= 1 + f; g *= 1 + f; b *= 1 + f; }
    return 'rgb(' + (r | 0) + ',' + (g | 0) + ',' + (b | 0) + ')';
}

// 스프라이트를 1회 베이크. colorMap._slug가 켜진 스프라이트는 메탈슬러그풍 후처리:
//  - 실루엣 바깥 1px 검은 외곽선 자동 생성
//  - 위가 뚫린 칸은 림라이트, 아래가 뚫린 칸은 셰이드
// flip이면 좌우 반전으로 베이크한다.
function bakePixelSprite(sprite, colorMap, flip) {
    const h = sprite.length, w = sprite[0].length;
    const slug = !!colorMap._slug;
    const pad = slug ? 1 : 0;
    const off = document.createElement('canvas');
    off.width = w + pad * 2;
    off.height = h + pad * 2;
    const octx = off.getContext('2d');
    const cell = (x, y) => {
        if (x < 0 || x >= w || y < 0 || y >= h) return 0;
        return sprite[y][flip ? w - 1 - x : x];
    };
    for (let y = 0; y < h; y++) {
        for (let x = 0; x < w; x++) {
            const v = cell(x, y);
            if (!v || !colorMap[v]) continue;
            let col = colorMap[v];
            if (slug) {
                if (!cell(x, y - 1)) col = _shadeColor(col, 0.45);
                else if (!cell(x, y + 1)) col = _shadeColor(col, -0.3);
            }
            octx.fillStyle = col;
            octx.fillRect(x + pad, y + pad, 1, 1);
        }
    }
    if (slug) {
        octx.fillStyle = '#100C08';
        for (let y = -1; y <= h; y++) {
            for (let x = -1; x <= w; x++) {
                if (cell(x, y)) continue;
                if (cell(x - 1, y) || cell(x + 1, y) || cell(x, y - 1) || cell(x, y + 1) ||
                    cell(x - 1, y - 1) || cell(x + 1, y - 1) || cell(x - 1, y + 1) || cell(x + 1, y + 1)) {
                    octx.fillRect(x + pad, y + pad, 1, 1);
                }
            }
        }
    }
    return off;
}
window.bakePixelSprite = bakePixelSprite;

function drawPixelSprite(sprite, colorMap, x, y, scale = PIXEL_SCALE, flipH = false) {
    if (!sprite || !colorMap) return;
    let entry = _spriteCache.get(sprite);
    if (!entry) { entry = {}; _spriteCache.set(sprite, entry); }
    const key = flipH ? 'f' : 'n';
    if (!entry[key]) entry[key] = bakePixelSprite(sprite, colorMap, flipH);
    const baked = entry[key];
    const pad = colorMap._slug ? scale : 0;
    ctx.imageSmoothingEnabled = false;
    ctx.drawImage(baked, x - pad, y - pad, baked.width * scale, baked.height * scale);
}
